SELECT
    cast(`key` AS STRING) AS externalId
  , CASE WHEN coalesce(trim(`pipingExternalId`), '') = '' THEN NULL ELSE node_reference(trim(`pipingSpace`), trim(`pipingExternalId`)) END AS `piping`
  , cast(`cmlId` AS STRING) AS `cmlId`
FROM `{{energyBaseRawDb}}`.`ConditionMonitoringLocation`
